"""Action functions for the MIAT AGV docking controller (pure, stateless per call)."""
import math
from sim.api import Command, IMG_W, FX, CAM_X, TAG_ID


def wrap(a):
    a = math.fmod(a, 2 * math.pi)
    if a > math.pi:
        a -= 2 * math.pi
    elif a <= -math.pi:
        a += 2 * math.pi
    return a


def sat(x, lim):
    return max(-lim, min(lim, x))


def _cam(px, py, yaw):
    return px + CAM_X * math.cos(yaw), py + CAM_X * math.sin(yaw)


def _beta_max(P):
    return math.radians(P['fov_half_deg'] - P['fov_margin_deg'])


def _rot_cmd(e, wmax):
    """In-place rotation rule (w + = left, e = target - current)."""
    if abs(e) > 0.12:
        w = sat(1.8 * e, wmax)
    else:
        w = math.copysign(min(0.15, wmax), e)
    return Command(0.0, w)


# ---------------- G0 ----------------
def a0_init():
    return Command(), True


def a1_check_sensors(odom, scan):
    return odom is not None and scan is not None


def a2_navigate():
    return True


def a6_docked():
    return Command()


def a9_abort():
    return Command()


# ---------------- G3 ----------------
def a30_enter():
    return Command(), None, [], False, False, True


def a31_search_rotate(P):
    return Command(0.0, P['w_search'])


def a331_bbox_center(det):
    return float(det.u)


def a332_pallet_distance(depth_samples):
    valid = [float(s) for s in depth_samples if s > 0.05]
    if len(valid) < 5:
        return 0.0, False
    m = _median(valid)
    kept = [s for s in valid if abs(s - m) <= 0.3]
    if len(kept) < 3:
        return 0.0, False
    return _median(kept), True


def _median(v):
    s = sorted(v)
    n = len(s)
    if n % 2:
        return s[n // 2]
    return 0.5 * (s[n // 2 - 1] + s[n // 2])


def a333_pallet_bearing(u):
    return math.atan((u - IMG_W / 2) / FX)


def a321_candidates(pallets, odom, blacklist, P):
    cands = []
    if not pallets:
        return cands
    cx = odom.x + CAM_X * math.cos(odom.yaw)
    cy = odom.y + CAM_X * math.sin(odom.yaw)
    for det in pallets:
        if det.score < P['score_min']:
            continue
        d, ok = a332_pallet_distance(det.depth_samples)
        if not ok:
            continue
        b = a333_pallet_bearing(a331_bbox_center(det))
        W = det.width_px * d / FX
        if not (P['width_min'] <= W <= P['width_max']):
            continue
        ba = wrap(odom.yaw - b)
        pos = (cx + d * math.cos(ba), cy + d * math.sin(ba))
        bad = False
        for bp in (blacklist or []):
            if math.hypot(pos[0] - bp[0], pos[1] - bp[1]) < 0.8:
                bad = True
                break
        if bad:
            continue
        cands.append({'ba': ba, 'd': d, 'b': b, 'W': W, 'score': det.score, 'pos': pos})
    return cands


def a322_confirm(cands, hist, t, P):
    window = P['confirm_window_s']
    new_hist = [h for h in (hist or []) if t - h['t'] <= window]
    for c in cands:
        new_hist.append({'t': t, 'c': c})
    tol = math.radians(P['confirm_tol_deg'])
    best = None
    best_n = 0
    for c in cands:
        stamps = set()
        for h in new_hist:
            hc = h['c']
            if abs(wrap(hc['ba'] - c['ba'])) <= tol and abs(hc['d'] - c['d']) <= 0.4:
                stamps.add(h['t'])
        n = len(stamps)
        if n > best_n or (n == best_n and best is not None and c['score'] > best['score']):
            best, best_n = c, n
    if best is not None and best_n >= P['confirm_k']:
        return new_hist, True, {'ba': best['ba'], 'd': best['d'], 'pos': best['pos'], 't': t}
    return new_hist, False, None


def a323_track(cands, track, t, P):
    if track is None:
        return None, True
    gate = math.radians(P['track_gate_deg'])
    best = None
    best_diff = None
    for c in cands:
        diff = abs(wrap(c['ba'] - track['ba']))
        if diff <= gate and abs(c['d'] - track['d']) < 0.6:
            if best is None or diff < best_diff:
                best, best_diff = c, diff
    new = dict(track)
    if best is not None:
        new['ba'] = wrap(track['ba'] + 0.5 * wrap(best['ba'] - track['ba']))
        new['pos'] = ((track['pos'][0] + best['pos'][0]) / 2.0,
                      (track['pos'][1] + best['pos'][1]) / 2.0)
        new['d'] = best['d']
        new['t'] = t
    lost = (t - new['t']) > P['track_lost_s']
    return new, lost


def a34_approach_cmd(track, odom, P):
    if track is None:
        return Command(), False
    cx = odom.x + CAM_X * math.cos(odom.yaw)
    cy = odom.y + CAM_X * math.sin(odom.yaw)
    dx = track['pos'][0] - cx
    dy = track['pos'][1] - cy
    d = math.hypot(dx, dy)
    b = wrap(odom.yaw - math.atan2(dy, dx))
    if d <= P['d_app']:
        if abs(b) <= math.radians(P['app_bear_tol_deg']):
            return Command(0.0, 0.0), True
        return Command(0.0, sat(-1.5 * b, 0.4)), False
    w = sat(-P['k_bear'] * b, 0.5)
    v = P['v_app'] if abs(b) < math.radians(10.0) else 0.05
    return Command(v, w), False


def a35_exit(track, odom):
    return Command(), {'ba': track['ba'], 'pos': track['pos']}, True


def a3e_fail():
    return Command(), True


# ---------------- G4 ----------------
def a40_enter(n_loc, est, P):
    n = n_loc + 1
    return Command(), n, n <= P['max_retries'], None, None, False, False, True


def a41_tag_sweep(odom, pallet_ref, sweep, P):
    if sweep is None:
        cx = odom.x + CAM_X * math.cos(odom.yaw)
        cy = odom.y + CAM_X * math.sin(odom.yaw)
        if pallet_ref is None:
            ref = odom.yaw
        else:
            p = pallet_ref['pos']
            ref = math.atan2(p[1] - cy, p[0] - cx)
        A = math.radians(P['tag_sweep_deg'])
        sweep = {'targets': [wrap(ref), wrap(ref + A), wrap(ref - A), wrap(ref)], 'i': 0}
    targets = sweep['targets']
    i = sweep['i']
    err = wrap(targets[i] - odom.yaw)
    if abs(err) < math.radians(3.0):
        cmd = Command()
        i = (i + 1) % len(targets)
    else:
        cmd = Command(0.0, sat(2.0 * err, P['w_tag']))
    return cmd, {'targets': list(targets), 'i': i}


def a42_tag_to_pose(tag):
    yaw = wrap(tag.yaw - math.pi / 2)
    cx = -(tag.z * math.cos(yaw) + tag.x * math.sin(yaw))
    cy = -(tag.z * math.sin(yaw) - tag.x * math.cos(yaw))
    return cx - CAM_X * math.cos(yaw), cy - CAM_X * math.sin(yaw), yaw


def a43_update_pose(est, odom, tags, t, P):
    meas = None
    for tg in (tags or []):
        if tg.id == TAG_ID:
            meas = a42_tag_to_pose(tg)
            break
    if est is None:
        if meas is None:
            return None
        return {'px': meas[0], 'py': meas[1], 'yaw': meas[2], 't_meas': t, 'n': 1,
                'rej': 0, 'o': (odom.x, odom.y, odom.yaw)}
    e = dict(est)
    ox, oy, oyaw = est['o']
    dx, dy = odom.x - ox, odom.y - oy
    f = dx * math.cos(oyaw) + dy * math.sin(oyaw)
    l = -dx * math.sin(oyaw) + dy * math.cos(oyaw)
    c, s = math.cos(est['yaw']), math.sin(est['yaw'])
    e['px'] = est['px'] + f * c - l * s
    e['py'] = est['py'] + f * s + l * c
    e['yaw'] = wrap(est['yaw'] + wrap(odom.yaw - oyaw))
    e['o'] = (odom.x, odom.y, odom.yaw)
    if meas is not None:
        ex, ey = meas[0] - e['px'], meas[1] - e['py']
        eyaw = wrap(meas[2] - e['yaw'])
        ccx, ccy = _cam(e['px'], e['py'], e['yaw'])
        cd = math.hypot(ccx, ccy)
        if math.hypot(ex, ey) <= P['gate_pos'] + 0.1 * cd and \
                abs(eyaw) <= math.radians(P['gate_yaw_deg']):
            k = 0.5 if e['n'] < P['init_meas'] else P['fuse_gain']
            e['px'] += k * ex
            e['py'] += k * ey
            e['yaw'] = wrap(e['yaw'] + k * eyaw)
            e['t_meas'] = t
            e['n'] = e['n'] + 1
            e['rej'] = 0
        else:
            e['rej'] = e['rej'] + 1
            if e['rej'] >= 5:
                e['px'], e['py'], e['yaw'] = meas
                e['t_meas'] = t
                e['n'] = 1
                e['rej'] = 0
    return e


def a44_pose_status(est, t, P):
    if est is None:
        return False, False, True
    age = t - est['t_meas']
    tag_ok = age < 0.35
    pose_ready = tag_ok and est['n'] >= P['init_meas']
    cx, cy = _cam(est['px'], est['py'], est['yaw'])
    cd = math.hypot(cx, cy)
    stale = (age > P['pose_stale_s'] and cd > P['near_dist']) or age > P['blind_max_s']
    return tag_ok, pose_ready, stale


def a42_hold():
    return Command()


def a43_publish(est):
    return est is not None


def a4e_blacklist(blacklist, pallet_ref):
    bl = list(blacklist or [])
    if pallet_ref is not None:
        bl.append(tuple(pallet_ref['pos']))
    return Command(), bl, True


# ---------------- G5 ----------------
def a50_enter():
    return Command(), None, 0, True, False, False, True


def a51_plan(est, P):
    if est is None:
        return Command(), False
    px, py = est['px'], est['py']
    if abs(px) <= 0.05 and abs(py - P['y_pre']) <= 0.15:
        return Command(), True
    if py <= P['y_pre'] + 0.15:
        return Command(), False
    gamma = math.atan2(abs(px), py - P['y_pre'])
    return Command(), gamma <= _beta_max(P) - math.radians(2.0)


def a52_reposition(est, mstate, P):
    if est is None:
        return Command(), mstate, False
    px, py, yaw = est['px'], est['py'], est['yaw']
    bm = _beta_max(P)
    if not mstate or mstate.get('owner') != '52':
        yw = max(py, P['y_pre'] + P['repos_extra'])
        sgn = 1.0 if px >= 0 else -1.0
        xw = sgn * (yw - P['y_pre']) * math.tan(bm - math.radians(8.0))
        mstate = {'owner': '52', 'phase': 'turn1', 'W': (xw, yw)}
    ms = dict(mstate)
    xw, yw = ms['W']
    dist = math.hypot(xw - px, yw - py)
    if ms['phase'] == 'turn1':
        if dist < 0.06:
            ms['phase'] = 'turn2'
        else:
            e = wrap(math.atan2(yw - py, xw - px) - yaw)
            if abs(e) < math.radians(3.0):
                ms['phase'] = 'drive'
            else:
                return _rot_cmd(e, 0.5), ms, False
    if ms['phase'] == 'drive':
        if dist < 0.06:
            ms['phase'] = 'turn2'
        else:
            e = wrap(math.atan2(yw - py, xw - px) - yaw)
            return Command(0.2 * max(0.0, math.cos(e)), sat(1.5 * e, 0.5)), ms, False
    # turn2
    cx, cy = _cam(px, py, yaw)
    e = wrap(math.atan2(-cy, -cx) - yaw)
    if abs(e) < math.radians(3.0):
        return Command(), None, True
    return _rot_cmd(e, 0.5), ms, False


def a53_converge(est, P):
    if est is None:
        return Command(), False, False
    px, py, yaw = est['px'], est['py'], est['yaw']
    y_pre = P['y_pre']
    if abs(px) <= 0.05 and py <= y_pre + 0.08:
        return Command(), True, False
    if py < y_pre - 0.25 and abs(px) > 0.10:
        return Command(), False, True
    ty = y_pre if py > y_pre else py - 0.3
    h = math.atan2(ty - py, -px)
    cx, cy = _cam(px, py, yaw)
    dir_t = math.atan2(-cy, -cx)
    bm = _beta_max(P)
    h = wrap(dir_t + sat(wrap(h - dir_t), bm))
    e = wrap(h - yaw)
    dist = math.hypot(px, py - y_pre)
    v = P['v_conv'] * max(0.0, math.cos(e)) * min(1.0, max(0.3, dist / 0.4))
    return Command(v, sat(P['k_head'] * e, 0.6)), False, False


def a54_reacquire(est, mstate, t, P):
    if est is None:
        return Command(0.0, 0.2), None
    cx, cy = _cam(est['px'], est['py'], est['yaw'])
    e = wrap(math.atan2(-cy, -cx) - est['yaw'])
    if abs(e) <= math.radians(4.0):
        return Command(), None
    return _rot_cmd(e, 0.4), None


def a55_final_approach(est, P):
    if est is None:
        return Command(), False
    px, py, yaw = est['px'], est['py'], est['yaw']
    ey = py - P['dock_y']
    if ey > 0.01:
        h = -math.pi / 2 - sat(math.atan(P['k_lat'] * px), math.radians(30.0))
        e = wrap(h - yaw)
        v = P['v_final'] * min(1.0, max(0.25, ey / 0.25)) * max(0.0, math.cos(e))
        return Command(v, sat(P['k_head'] * e, 0.5)), False
    e = wrap(-math.pi / 2 - yaw)
    if abs(e) <= math.radians(P['head_tol_deg']):
        return Command(), True
    return _rot_cmd(e, 0.3), False


def a56_verify(est, mstate, t, P):
    if not mstate or mstate.get('owner') != '56':
        mstate = {'owner': '56', 't0': t}
    if t - mstate['t0'] < P['verify_s'] - 1e-9:
        return Command(), mstate, False, False, False
    ok = (est is not None
          and abs(est['px']) <= P['verify_lat']
          and abs(est['py'] - P['dock_y']) <= P['verify_dist']
          and abs(wrap(est['yaw'] + math.pi / 2)) <= math.radians(P['verify_head_deg']))
    return Command(), None, ok, not ok, ok


def a57_backoff(odom, mstate, n_bo, P):
    if not mstate or mstate.get('owner') != '57':
        mstate = {'owner': '57', 'o0': (odom.x, odom.y)}
        n_bo = n_bo + 1
    bo_ok = n_bo < P['max_backoff']
    dist = math.hypot(odom.x - mstate['o0'][0], odom.y - mstate['o0'][1])
    if dist >= P['backoff_dist']:
        return Command(), None, n_bo, bo_ok, True
    return Command(-0.15, 0.0), mstate, n_bo, bo_ok, False


def a5e_fail():
    return Command(), True
